import{_ as p,a0 as t,w as d,s as o,ao as r,I as l,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"把 Linux 上的文件列表和排序玩出花來 | LCTT x X-CMD","titleTemplate":false,"description":"把 Linux 上的文件列表和排序玩出花來 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"把 Linux 上的文件列表和排序玩出花來 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"把 Linux 上的文件列表和排序玩出花來 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200825 11 ways to list and sort files on Linux","title":"把 Linux 上的文件列表和排序玩出花來","tag":"202008","desc":""},"relativePath":"202008/20200825 11 ways to list and sort files on Linux.md","filePath":"[post].md"}'),c={name:"202008/20200825 11 ways to list and sort files on Linux.md"};function h(g,s,b,k,u,z){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="把-linux-上的文件列表和排序玩出花來" tabindex="-1">把 Linux 上的文件列表和排序玩出花來 <a class="header-anchor" href="#把-linux-上的文件列表和排序玩出花來" aria-label="Permalink to “把 Linux 上的文件列表和排序玩出花來”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202008/28/213742y8cxnbnjpopzd5j0.jpg" alt=""></p><blockquote><p>Linux 命令可以提供文件的詳細信息，也可以自定義顯示的文件列表，甚至可以深入到文件系統的目錄中，只要你願意看。</p></blockquote><p>在 Linux 系統上，有許多方法可以列出文件並顯示它們的信息。這篇文章回顧了一些提供文件細節的命令，並提供了自定義文件列表的選項，以滿足你的需求。</p><p>大多數命令都會列出單個目錄中的文件，而其他命令則可以深入到文件系統的目錄中，只要你願意看。</p><p>當然，最主要的文件列表命令是 <code>ls</code>。然而，這個命令有大量的選項，可以只查找和列出你想看的文件。另外，還有 <code>find</code> 可以幫助你進行非常具體的文件搜索。</p><h3 id="按名稱列出文件" tabindex="-1">按名稱列出文件 <a class="header-anchor" href="#按名稱列出文件" aria-label="Permalink to “按名稱列出文件”">​</a></h3><p>最簡單的方法是使用 <code>ls</code> 命令按名稱列出文件。畢竟，按名稱（字母數字順序）列出文件是默認的。你可以選擇 <code>ls</code>（無細節）或 <code>ls -l</code>（大量細節）來決定你看到什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls | head -6</span></span>
<span class="line"><span>8pgs.pdf</span></span>
<span class="line"><span>Aesthetics_Thank_You.pdf</span></span>
<span class="line"><span>alien.pdf</span></span>
<span class="line"><span>Annual_Meeting_Agenda-20190602.pdf</span></span>
<span class="line"><span>bigfile.bz2</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>$ ls -l | head -6</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs      10886 Mar 22  2019 8pgs.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs     284003 May 11  2019 Aesthetics_Thank_You.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs      38282 Jan 24  2019 alien.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs      97358 May 19  2019 Annual_Meeting_20190602.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs   18115234 Apr 16 17:36 bigfile.bz2</span></span>
<span class="line"><span>drwxrwxr-x  4 shs     shs    8052736 Jul 10 13:17 bin</span></span></code></pre></div><p>如果你想一次查看一屏的列表，可以將 <code>ls</code> 的輸出用管道送到 <code>more</code> 命令中。</p><h3 id="按相反的名字順序排列文件" tabindex="-1">按相反的名字順序排列文件 <a class="header-anchor" href="#按相反的名字順序排列文件" aria-label="Permalink to “按相反的名字順序排列文件”">​</a></h3><p>要按名稱反轉文件列表，請添加 <code>-r</code>（<ruby>反轉<rt>Reverse</rt></ruby>）選項。這就像把正常的列表倒過來一樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -r</span></span>
<span class="line"><span>$ ls -lr</span></span></code></pre></div><h3 id="按文件擴展名列出文件" tabindex="-1">按文件擴展名列出文件 <a class="header-anchor" href="#按文件擴展名列出文件" aria-label="Permalink to “按文件擴展名列出文件”">​</a></h3><p><code>ls</code> 命令不會按內容分析文件類型，它只會處理文件名。不過，有一個命令選項可以按擴展名列出文件。如果你添加了 <code>-X</code> （<ruby>擴展名<rt>eXtension</rt></ruby>）選項，<code>ls</code> 將在每個擴展名類別中按名稱對文件進行排序。例如，它將首先列出沒有擴展名的文件（按字母數字順序），然後是擴展名為 <code>.1</code>、<code>.bz2</code>、<code>.c</code> 等的文件。</p><h3 id="只列出目錄" tabindex="-1">只列出目錄 <a class="header-anchor" href="#只列出目錄" aria-label="Permalink to “只列出目錄”">​</a></h3><p>默認情況下，<code>ls</code> 命令將同時顯示文件和目錄。如果你想只列出目錄，你可以使用 <code>-d</code>（<ruby>目錄<rt>Directory</rt></ruby>）選項。你會得到一個像這樣的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -d */</span></span>
<span class="line"><span>1/     backups/     modules/       projects/     templates/</span></span>
<span class="line"><span>2/     html/        patches/       public/       videos/</span></span>
<span class="line"><span>bin/   new/         private/       save/</span></span></code></pre></div><h3 id="按大小排列文件" tabindex="-1">按大小排列文件 <a class="header-anchor" href="#按大小排列文件" aria-label="Permalink to “按大小排列文件”">​</a></h3><p>如果你想按大小順序列出文件，請添加 <code>-S</code>（<ruby>大小<rt>Size</rt></ruby>）選項。但請注意，這實際上不會顯示文件的大小（以及其他文件的細節），除非你還添加 <code>-l</code>（<ruby>長列表<rt>Long listing</rt></ruby>）選項。當按大小列出文件時，一般來説，看到命令在按你的要求做事情是很有幫助的。注意，默認情況下是先顯示最大的文件。添加 <code>-r</code> 選項可以反過來（即 <code>ls -lSr</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lS</span></span>
<span class="line"><span>total 959492</span></span>
<span class="line"><span>-rw-rw-r--  1 shs   shs  357679381 Sep 19  2019 sav-linux-free-9.tgz</span></span>
<span class="line"><span>-rw-rw-r--  1 shs   shs  103270400 Apr 16 17:38 bigfile</span></span>
<span class="line"><span>-rw-rw-r--  1 shs   shs   79117862 Oct  5  2019 Nessus-8.7.1-ubuntu1110_amd64.deb</span></span></code></pre></div><h3 id="按屬主列出文件" tabindex="-1">按屬主列出文件 <a class="header-anchor" href="#按屬主列出文件" aria-label="Permalink to “按屬主列出文件”">​</a></h3><p>如果你想按屬主列出文件（例如，在一個共享目錄中），你可以把 <code>ls</code> 命令的輸出傳給 <code>sort</code>，並通過添加 <code>-k3</code> 來按第三個字段排序，從而挑出屬主一欄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l | sort -k3 | more</span></span>
<span class="line"><span>total 56</span></span>
<span class="line"><span>-rw-rw-r-- 1 dory  shs      0 Aug 23 12:27 tasklist</span></span>
<span class="line"><span>drwx------ 2 gdm   gdm   4096 Aug 21 17:12 tracker-extract-files.121</span></span>
<span class="line"><span>srwxr-xr-x 1 root  root     0 Aug 21 17:12 ntf_listenerc0c6b8b4567</span></span>
<span class="line"><span>drwxr-xr-x 2 root  root  4096 Aug 21 17:12 hsperfdata_root</span></span>
<span class="line"><span>              ^</span></span>
<span class="line"><span>              |</span></span></code></pre></div><p>事實上，你可以用這種方式對任何字段進行排序（例如，年份）。只是要注意，如果你要對一個數字字段進行排序，則要加上一個 <code>n</code>，如 <code>-k5n</code>，否則你將按字母數字順序進行排序。這種排序技術對於文件內容的排序也很有用，而不僅僅是用於列出文件。</p><h3 id="按年份排列文件" tabindex="-1">按年份排列文件 <a class="header-anchor" href="#按年份排列文件" aria-label="Permalink to “按年份排列文件”">​</a></h3><p>使用 <code>-t</code>（<ruby>修改時間<rt>Time modified</rt></ruby>）選項按年份順序列出文件 —— 它們的新舊程度。添加 <code>-r</code> 選項，讓最近更新的文件在列表中最後顯示。我使用這個別名來顯示我最近更新的文件列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias recent=&#39;ls -ltr | tail -8&#39;</span></span></code></pre></div><p>請注意，文件的更改時間和修改時間是不同的。<code>-c</code>（<ruby>更改時間<rt>time Changed</rt></ruby>）和 <code>-t</code>（修改時間）選項的結果並不總是相同。如果你改變了一個文件的權限，而沒有改變其他內容，<code>-c</code> 會把這個文件放在 <code>ls</code> 輸出的頂部，而 <code>-t</code> 則不會。如果你想知道其中的區別，可以看看 <code>stat</code> 命令的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat ckacct</span></span>
<span class="line"><span>  File: ckacct</span></span>
<span class="line"><span>  Size: 200             Blocks: 8          IO Block: 4096   regular file</span></span>
<span class="line"><span>Device: 801h/2049d      Inode: 829041      Links: 1</span></span>
<span class="line"><span>Access: (0750/-rwxr-x---)  Uid: ( 1000/     shs)   Gid: ( 1000/     shs)</span></span>
<span class="line"><span>Access: 2020-08-20 16:10:11.063015008 -0400</span></span>
<span class="line"><span>Modify: 2020-08-17 07:26:34.579922297 -0400 &lt;== content changes</span></span>
<span class="line"><span>Change: 2020-08-24 09:36:51.699775940 -0400 &lt;== content or permissions changes</span></span>
<span class="line"><span> Birth: -</span></span></code></pre></div><h3 id="按組別列出文件" tabindex="-1">按組別列出文件 <a class="header-anchor" href="#按組別列出文件" aria-label="Permalink to “按組別列出文件”">​</a></h3><p>要按關聯的組別對文件進行排序，你可以將一個長列表的輸出傳給 <code>sort</code> 命令，並告訴它在第 4 列進行排序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l | sort -k4</span></span></code></pre></div><h3 id="按訪問日期列出文件" tabindex="-1">按訪問日期列出文件 <a class="header-anchor" href="#按訪問日期列出文件" aria-label="Permalink to “按訪問日期列出文件”">​</a></h3><p>要按訪問日期（最近訪問的日期在前）列出文件，使用 <code>-ltu</code> 選項。<code>u</code> 強制“按訪問日期”排列順序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ltu</span></span>
<span class="line"><span>total 959500</span></span>
<span class="line"><span>-rwxr-x---  1 shs     shs        200 Aug 24 09:42 ckacct  &lt;== most recently used</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs       1335 Aug 23 17:45 lte</span></span></code></pre></div><h3 id="單行列出多個文件" tabindex="-1">單行列出多個文件 <a class="header-anchor" href="#單行列出多個文件" aria-label="Permalink to “單行列出多個文件”">​</a></h3><p>有時，精簡的文件列表更適合手頭的任務。<code>ls</code> 命令甚至有這方面的選項。為了在儘可能少的行上列出文件，你可以使用 <code>--format=comma</code> 來用逗號分隔文件名，就像這個命令一樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --format=comma</span></span>
<span class="line"><span>1, 10, 11, 12, 124, 13, 14, 15, 16pgs-landscape.pdf, 16pgs.pdf, 17, 18, 19,</span></span>
<span class="line"><span>192.168.0.4, 2, 20, 2018-12-23_OoS_2.pdf, 2018-12-23_OoS.pdf, 20190512_OoS.pdf,</span></span>
<span class="line"><span>&#39;2019_HOHO_application working.pdf&#39; …</span></span></code></pre></div><p>喜歡用空格？使用 <code>--format=across</code> 代替。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --format=across z*</span></span>
<span class="line"><span>z              zip            zipfiles      zipfiles1.bat   zipfiles2.bat</span></span>
<span class="line"><span>zipfiles3.bat  zipfiles4.bat  zipfiles.bat  zoom_amd64.deb  zoomap.pdf</span></span>
<span class="line"><span>zoom-mtg</span></span></code></pre></div><h3 id="增加搜索的深度" tabindex="-1">增加搜索的深度 <a class="header-anchor" href="#增加搜索的深度" aria-label="Permalink to “增加搜索的深度”">​</a></h3><p>雖然 <code>ls</code> 一般只列出單個目錄中的文件，但你可以選擇使用 <code>-R</code> 選項（<ruby>遞歸<rt>Recursively</rt></ruby>）地列出文件，深入到整個目錄的深處。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -R zzzzz | grep -v &quot;^$&quot;</span></span>
<span class="line"><span>zzzzz:</span></span>
<span class="line"><span>zzzz</span></span>
<span class="line"><span>zzzzz/zzzz:</span></span>
<span class="line"><span>zzz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz:</span></span>
<span class="line"><span>zz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz/zz:</span></span>
<span class="line"><span>z</span></span>
<span class="line"><span>zzzzz/zzzz/zzz/zz/z:</span></span>
<span class="line"><span>sleeping</span></span></code></pre></div><p>另外，你也可以使用 <code>find</code> 命令，對深度進行限制或不限制。在這個命令中，我們指示 <code>find</code> 命令只在三個層次的目錄中查找：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find zzzzz -maxdepth 3</span></span>
<span class="line"><span>zzzzz</span></span>
<span class="line"><span>zzzzz/zzzz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz/zz</span></span></code></pre></div><h3 id="選擇-ls-還是-find" tabindex="-1">選擇 ls 還是 find <a class="header-anchor" href="#選擇-ls-還是-find" aria-label="Permalink to “選擇 ls 還是 find”">​</a></h3><p>當你需要列出符合具體要求的文件時，<code>find</code> 命令可能是比 <code>ls</code> 更好的工具。</p><p>與 <code>ls</code> 不同的是，<code>find</code> 命令會盡可能地深入查找，除非你限制它。它還有許多其他選項和一個 <code>-exec</code> 子命令，允許在找到你要找的文件後採取一些特定的行動。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>ls</code> 命令有很多用於列出文件的選項。瞭解一下它們。你可能會發現一些你會喜歡的選項。</p><hr>`,52)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3572590/11-ways-to-list-and-sort-files-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3572590/11-ways-to-list-and-sort-files-on-linux.html",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=p(c,[["render",h]]);export{x as __pageData,y as default};
